#!/usr/bin/env python3
"""Builds database/data/catalog.json from the compact curated tables below."""
import json, re, sys

def slug(s):
    import unicodedata
    s = unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode()
    return re.sub(r'[^a-z0-9]+', '-', s.lower()).strip('-')

